export default function main({ rows, now }) {
  const today = String(now).slice(0, 10);
  const overdue = rows.filter(r => String(r.status ?? '').trim().toLowerCase() !== 'done' && r.due && String(r.due).slice(0, 10) < today && r.owner_email);
  const byOwner = new Map();
  for (const r of overdue) { const k = String(r.owner_email).trim().toLowerCase(); if (!byOwner.has(k)) byOwner.set(k, []); byOwner.get(k).push(r); }
  const mails = [...byOwner].map(([to, list]) => ({ to, subject: `You have ${list.length} overdue task(s)`, body: ['These tasks are overdue:', ...list.map(r => `- ${r.title} (due ${r.due})`)].join('\n') }));
  return { mails, count: overdue.length, post: overdue.length > 0, text: `${overdue.length} task(s) are overdue today (${today}).`, updates: overdue.map(r => ({ task_id: r.task_id, reminded_on: today })) };
}

export default function main({ body, rows, now }) {
  const s = v => (v === undefined || v === null ? '' : String(v).trim());
  const email = s(body.email).toLowerCase(), name = s(body.name);
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return { valid: false, status: 400, answer: { ok: false, error: 'invalid email' }, rows: [] };
  const old = rows.find(r => s(r.email).toLowerCase() === email);
  return { valid: true, status: 200, answer: { ok: true }, rows: [{ email, name, visits: old ? (Number(old.visits) || 0) + 1 : 1, last_seen: now }] };
}
